properties.query:
let windowSize = 30m;
let ApprovedOps = _GetWatchlist('Approved_Operators_List') | project OperatorId;
// S23: telemetry-tap 강제 중단
let S23 =
    UAVServiceAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where ContainerName == 'telemetry-tap'
    | where Action in ('stop','kill')
    | project T1=TimeGenerated, ContainerName;
// S6: 탐지 맹점 구간 내 GCS 비인가 로그인
let S6 =
    UAVOpAudit_CL
    | where TimeGenerated > ago(windowSize)
    | where EventType == 'login_success'
    | where Operator !in (ApprovedOps)
    | project T2=TimeGenerated, OperatorId=Operator;
S23
| join kind=inner (S6)
    on $left.T1 <= $right.T2
    and $right.T2 <= ($left.T1 + 20m)
| extend BlindWindowMin = datetime_diff('minute', T2, T1)
| extend CampaignType = "C7_서비스중단_탐지맹점_GCS침해"
| extend StepSummary = strcat("S23@", tostring(T1), "(telemetry-tap종료) → S6@", tostring(T2), "(맹점", tostring(BlindWindowMin), "분후)")
| extend Severity = "High"
| project T1, T2, ContainerName, OperatorId, BlindWindowMin, CampaignType, StepSummary, Severity
